let residue_TYBIJ = new_type_definition "residue" ("mk_residue",
 "dest_residue")
  (prove(`?(f:A->num). !(p:A) (q:A). f p = f q`,
   EXISTS_TAC `\(p:A). (ARB:num)` THEN REWRITE_TAC[]));;

let Residue_DEF = new_definition
  `Residue (x:num) = (mk_residue (\(p:A). x):(A)residue)`;;

let residue_rep_DEF = new_definition
  `residue_rep (r:(A)residue) = dest_residue r (ARB:A)`;;

let residue_SEL_CTR, residue_CTR_SEL, residue_INJECT =
  fips_phantom_theorems residue_TYBIJ Residue_DEF residue_rep_DEF;;

