let fips204_poly_TYBIJ = new_type_definition "fips204_poly"
 ("mk_fips204_poly", "dest_fips204_poly")
  (prove(`?(f:A->(fips204_zq)list). !(p:A) (q:A). f p = f q`,
   EXISTS_TAC `\(p:A). (ARB:(fips204_zq)list)` THEN REWRITE_TAC[]));;

let FIPS204_Poly_DEF = new_definition
