(* Constants *)

let residue_of_int_mod_DEF = new_definition
  `!(v:int).
   residue_of_int_mod v =
     ((Residue:(num->(Q)residue))
      (isa_nat (isa_int_mod v (int_of_num (dimindex(:Q))))))`;;

let case_native_result_DEF = new_recursive_definition native_result_RECURSION
  `(!(f1:(A->B)) (f2:(fault->B)) (f3:B) (x1:A).
    ((case_native_result f1 f2 f3 (Value x1)) = (f1 x1))) /\
   (!(f1:(A->B)) (f2:(fault->B)) (f3:B) (x2:fault).
    ((case_native_result f1 f2 f3 ((Fault:(fault->(A)native_result)) x2)) =
     (f2 x2))) /\
   (!(f1:(A->B)) (f2:(fault->B)) (f3:B).
    ((case_native_result f1 f2 f3 (Nontermination:(A)native_result)) = f3))`;;

let native_bind_DEF = new_definition
  `!(answer:(A)native_result) (rest:(A->(B)native_result)).
   native_bind answer rest =
     (case_native_result
      (\(value:A). (rest value))
      (\(failure:fault). ((Fault:(fault->(B)native_result)) failure))
      (Nontermination:(B)native_result)
      answer)`;;

let native_foldl_DEF = new_recursive_definition list_RECURSION
  `(!(body:(I->(S->(S)native_result))) (s:S).
    ((native_foldl body ([]:(I)list) s) = (Value s))) /\
   (!(body:(I->(S->(S)native_result))) (i:I) (indices:(I)list) (s:S).
    ((native_foldl body (CONS i indices) s) =
     (native_bind (body i s) (native_foldl body indices))))`;;

let typed_hol_read_DEF = new_definition
  `!(r:(A)option).
   typed_hol_read r =
     (isa_case_option
      ((Fault:(fault->(A)native_result)) Bounds_Error)
      (\(x:A). (Value x))
      r)`;;

let native_list_index_DEF = new_definition
  `!(xs:(A)list) (i:int).
   native_list_index xs i =
     (if ((int_le (&0:int) i) /\ (int_lt i (int_of_num (LENGTH xs))))
      then (SOME (EL (isa_nat i) xs))
      else (NONE:(A)option))`;;

let fips204_zq_residue_DEF = new_recursive_definition fips204_zq_RECURSION
  `(!(x:(8380417)residue). ((fips204_zq_residue (FIPS204_Zq x)) = x))`;;

let typed_hol_nominal_update_DEF = new_definition
  `!(con:(A->B)) (sel:(B->A)) (inner:(A->(A)option)) (y:B).
   typed_hol_nominal_update con sel inner y =
     (isa_map_option con (inner (sel y)))`;;

let native_list_update_DEF = new_definition
  `!(xs:(A)list) (i:int) (a:A).
   native_list_update xs i a =
     (if ((int_le (&0:int) i) /\ (int_lt i (int_of_num (LENGTH xs))))
      then (SOME (isa_list_update xs (isa_nat i) a))
      else (NONE:((A)list)option))`;;

let native_schedule_DEF = new_recursive_definition num_RECURSION
  `(!(guard:(I->bool)) (next:(I->I)) (i:I).
    ((native_schedule 0 guard next i) = ([]:(I)list))) /\
   (!(n:num) (guard:(I->bool)) (next:(I->I)) (i:I).
    ((native_schedule (SUC n) guard next i) =
     (if (guard i)
      then (CONS i (native_schedule n guard next (next i)))
      else ([]:(I)list))))`;;

